func stageOperation(c *campaignState, cd *campaignDevice, stage string) *Operation {
    op := &Operation{CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: stage, ID: opFor(cd, stage).ID}
    if stage == StageRollback {
        op.TargetVersion = cd.RollbackTarget
    }
    return op
}
```

Careful: for unknown stage, opFor defaults to Download — but stageOperation is only called with valid stages. Same for opFor loop. Fine.

