// resultMatches 判断提交是否为已接受结果的重复提交（同一操作、相同结果）。
// 安装成功结果还须附带相同的上报（序号、版本、配置）；发生时间不参与判定，
// 使活动结束后的重复提交仍然有效。
func resultMatches(op *opState, res OperationResult) bool {
	if op.Success != res.Success || op.Reason != res.Reason {
		return false
	}
	if op.Success && op.ResultSeq != 0 {
		return op.ResultSeq == res.Seq &&
			op.ResultVersion == res.Version &&
			rawEqual(op.ResultConfig, res.Config)
	}
	return true
}

// acceptFailure 接受一次失败结果并按统一规则记录，是下载失败、安装失败
// （含开启回滚时）与回滚失败共用的唯一记录入口：
// 先在操作上记下首次接受的原因与时间，再向结果历史追加恰好一条记录
// （对应这台设备、这次操作与所处阶段），最后按阶段与活动配置决定设备的
// 后续状态。失败结果本身不更新设备版本、在线状态或上报配置，也不修改
// 期望配置、修订号及审计。调用前须已校验原因非空、操作已领取且尚未接受
// 结果、提交时间早于截止时间。
func (s *Store) acceptFailure(c *campaignState, cd *campaignDevice, stage, reason string, at time.Time) {
	op := opFor(cd, stage)
	op.HasResult = true
	op.Success = false
	op.Reason = reason
	op.At = at
	c.Results = append(c.Results, ResultRecord{
		DeviceID:    cd.DeviceID,
		OperationID: op.ID,
		Stage:       stage,
		Success:     false,
		Reason:      reason,
		At:          at,
	})
	switch {
	case stage == StageInstall && c.RollbackOnFailure:
		// 安装失败且开启回滚：保留原失败原因与时间，设备转入等待回滚
		// （非终态）；同批其他设备继续，后续批次立即记为未执行，
		// 活动不结束，要等回滚结束。
		cd.Status = DeviceAwaitingRollback
		cd.Phase = StageRollback
		cd.Reason = reason
		cd.At = at
		skipLaterBatches(c, cd, at)
	case stage == StageRollback:
		// 回滚失败：设备以回滚失败结束，影子不变。
		cd.Status = DeviceRollbackFailed
		cd.Phase = StageRollback
		cd.Reason = reason
		cd.At = at
		s.settle(c, at)
	default:
		// 下载失败（含领取前复查版本不兼容）或未开启回滚时的安装失败：
		// 设备失败，同批其他设备继续，后续批次记为未执行；
		// 全部设备进入终态时活动失败结束。
		cd.Status = DeviceFailed
		cd.Phase = stage
		cd.Reason = reason
		cd.At = at
		skipLaterBatches(c, cd, at)
		s.settle(c, at)
	}
}

// skipLaterBatches 把后续批次中尚未结束的设备立即记为未执行。
func skipLaterBatches(c *campaignState, cd *campaignDevice, at time.Time) {
	for _, other := range c.Devices {
		if other.Batch > cd.Batch && !isTerminal(other.Status) {
			other.Status = DeviceSkipped
			other.Phase = pendingPhase(other)
			other.Reason = "not executed: previous batch failed"
			other.At = at
		}
	}
}

// opFor 返回设备在指定阶段的操作状态，是（设备, 阶段）到操作状态的唯一映射。
func opFor(cd *campaignDevice, stage string) *opState {
	switch stage {
	case StageInstall:
		return &cd.Install
	case StageRollback:
		return &cd.Rollback
	default:
		return &cd.Download
	}
}

// pendingPhase 返回设备尚未完成的阶段：下载成功后停留在安装阶段。
func pendingPhase(cd *campaignDevice) string {
	if cd.Download.HasResult && cd.Download.Success {
		return StageInstall
	}
